number-of-segments-in-a-string:
class Solution:
    def countSegments(self, s: str) -> int:
        return len(s.split())

number-of-steps-to-reduce-a-number-to-ze:
class Solution:
    def numberOfSteps(self, num: int) -> int:
        cnt = 0
        while num:
            if num % 2:
                num -= 1
            else:
                num //= 2
            cnt += 1
        return cnt

number-of-students-doing-homework-at-a-g:
class Solution:
    def busyStudent(self, startTime: list[int], endTime: list[int], queryTime: int) -> int:
        cnt = 0
        for a, b in zip(startTime, endTime):
            if a <= queryTime <= b:
                cnt += 1
        return cnt

number-of-valid-clock-times:
class Solution:
    def countTime(self, time: str) -> int:
        h = 0
        for i in range(24):
            hh = str(i).zfill(2)
            if (time[0] == '?' or time[0] == hh[0]) and (time[1] == '?' or time[1] == hh[1]):
                h += 1
        m = 0
        for i in range(60):
            mm = str(i).zfill(2)
            if (time[3] == '?' or time[3] == mm[0]) and (time[4] == '?' or time[4] == mm[1]):
                m += 1
        return h * m

occurrences-after-bigram:
class Solution:
    def findOcurrences(self, text: str, first: str, second: str) -> list[str]:
        w = text.split()
        out = []
        for i in range(len(w) - 2):
            if w[i] == first and w[i + 1] == second:
                out.append(w[i + 2])
        return out

pascals-triangle:
class Solution:
    def generate(self, numRows: int) -> list[list[int]]:
        if numRows < 1:
            return []
        out = [[1]]
        for _ in range(1, numRows):
            prev = out[-1]
            row = [1]
            for i in range(len(prev) - 1):
                row.append(prev[i] + prev[i + 1])
            row.append(1)
            out.append(row)
        return out

pascals-triangle-ii:
class Solution:
    def getRow(self, rowIndex: int) -> list[int]:
        row = [1]
        for _ in range(rowIndex):
            nxt = [1]
            for i in range(len(row) - 1):
                nxt.append(row[i] + row[i + 1])
            nxt.append(1)
            row = nxt
        return row

path-crossing:
class Solution:
    def isPathCrossing(self, path: str) -> bool:
        x = 0
        y = 0
        seen = {(0, 0)}
        for c in path:
            if c == 'N':
                y += 1
            elif c == 'S':
                y -= 1
            elif c == 'E':
                x += 1
            else:
                x -= 1
            if (x, y) in seen:
                return True
            seen.add((x, y))
        return False

percentage-of-letter-in-string:
class Solution:
    def percentageLetter(self, s: str, letter: str) -> int:
        return s.count(letter) * 100 // len(s)

perfect-number:
class Solution:
    def checkPerfectNumber(self, num: int) -> bool:
        if num <= 1:
            return False
        total = 1
        d = 2
        while d * d <= num:
            if num % d == 0:
                total += d
                if d * d != num:
                    total += num // d
            d += 1
        return total == num

power-of-four:
class Solution:
    def isPowerOfFour(self, n: int) -> bool:
        return n > 0 and (n & (n - 1)) == 0 and (n - 1) % 3 == 0

power-of-three:
class Solution:
    def isPowerOfThree(self, n: int) -> bool:
        if n < 1:
            return False
        while n % 3 == 0:
            n //= 3
        return n == 1

power-of-two:
class Solution:
    def isPowerOfTwo(self, n: int) -> bool:
        return n > 0 and (n & (n - 1)) == 0

prime-number-of-set-bits-in-binary-repre:
class Solution:
    def countPrimeSetBits(self, left: int, right: int) -> int:
        primes = {2, 3, 5, 7, 11, 13, 17, 19}
        cnt = 0
        for n in range(left, right + 1):
            if bin(n).count('1') in primes:
                cnt += 1
        return cnt

range-addition-ii:
class Solution:
    def maxCount(self, m: int, n: int, ops: list[list[int]]) -> int:
        a = m
        b = n
        for x, y in ops:
            if x < a:
                a = x
            if y < b:
                b = y
        return a * b
